#include "scamptrie_dynamic.h"
#include "image_io.hpp"
#include <iostream>
#include <memory>
#include <stdexcept>
#include <vector>
#include <sys/wait.h>
#include <cstdlib>
int main(){
 try{
    std::ios::sync_with_stdio(false);std::cin.tie(nullptr);
    size_t cases;std::cin>>cases;std::cout<<"{\"results\":[";
    for(size_t c=0;c<cases;++c){
        if(c)std::cout<<',';auto live=std::unique_ptr<ScampTrieDynamic>(new ScampTrieDynamic());
        live->set_insert_prefix_timing_enabled(false);MemoryImage loaded;
        std::vector<nexthop_t> answers;std::vector<ImageData> saved;std::vector<bool> loads;
        size_t count;std::cin>>count;
        for(size_t i=0;i<count;++i){
            char op;std::cin>>op;
            if(op=='P'){auto ip=read_ip();unsigned len;uint64_t hop;std::cin>>len>>hop;
                if(live->insert_prefix(ip,len,hop)!=SCAMPTRIE_OK)throw std::runtime_error("put failed");}
            else if(op=='Q'||op=='I'){size_t n;std::cin>>n;for(size_t j=0;j<n;++j){auto ip=read_ip();uint32_t marker=0;answers.push_back(op=='Q'?live->lookup(ip,marker):loaded.lookup(ip));}}
            else if(op=='S'){auto exporter=std::unique_ptr<MemInit>(new MemInit(live.get()));saved.push_back(exporter->capture());}
            else if(op=='R'){size_t id;std::cin>>id;loads.push_back(loaded.load(saved.at(id)));}
            else if(op=='L'){auto d=image_read_wire();loads.push_back(loaded.load(d));}
            else throw std::runtime_error("wire opcode");
        }
        if(!std::cin)throw std::runtime_error("wire exhausted");
        std::cout<<"{\"answers\":[";for(size_t i=0;i<answers.size();++i){if(i)std::cout<<',';if(answers[i]==LPM_INVALID_NH)std::cout<<"null";else std::cout<<answers[i];}
        std::cout<<"],\"snapshots\":[";for(size_t i=0;i<saved.size();++i){if(i)std::cout<<',';image_write_json(saved[i]);}
        std::cout<<"],\"loads\":[";for(size_t i=0;i<loads.size();++i){if(i)std::cout<<',';std::cout<<(loads[i]?"true":"false");}std::cout<<"]}";
    }
    std::cout<<"]}\n";
    if(const char* feed=std::getenv("SCAMP_FEED_PID")){int status;waitpid(std::strtol(feed,nullptr,10),&status,0);}
    return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
}
#ifndef SCAMP_IMAGE_HPP
#define SCAMP_IMAGE_HPP
#include "scamptrie_base.h"
#include <array>
#include <bitset>
#include <cstdint>
#include <string>
#include <vector>
struct ImageLoc { int stage=-1; uint32_t cell=0; };
struct ImageFront { uint64_t key; ImageLoc loc; };
struct ImageData {
    ImageLoc root;
    std::vector<ImageFront> front16,front64;
    std::array<uint32_t,RAM_NUM> cells{};
    std::array<std::vector<std::bitset<256>>,RAM_NUM> banks;
    std::vector<uint64_t> bitmaps;
    std::vector<uint32_t> nexthops;
};
class MemoryImage {
public:
    MemoryImage() = default;
    // Validate the complete self-contained image before replacing loaded state.
    bool load(const ImageData& proposed);
    nexthop_t lookup(ip6_t ip) const;
private:
    ImageData data_;
};
std::string image_word_hex(const std::bitset<256>& bits);
std::bitset<256> image_word_from_hex(const std::string& text);
#endif
#include "image.hpp"
#include <stdexcept>
std::string image_word_hex(const std::bitset<256>& bits){
    std::string out(64,'0');for(int i=0;i<64;++i){unsigned v=0;for(int b=0;b<4;++b)v|=bits[4*i+b]?1u<<b:0;out[63-i]="0123456789abcdef"[v];}return out;
}
std::bitset<256> image_word_from_hex(const std::string& text){
    if(text.size()!=64)throw std::runtime_error("word length");std::bitset<256> out;
    for(int i=0;i<64;++i){char c=text[63-i];unsigned v=c<='9'?c-'0':c-'a'+10;if(v>15)throw std::runtime_error("word hex");for(int b=0;b<4;++b)out[4*i+b]=(v>>b)&1;}return out;
}
bool MemoryImage::load(const ImageData& proposed){return false;}
nexthop_t MemoryImage::lookup(ip6_t ip)const{return LPM_INVALID_NH;}
#ifndef SCAMP_IMAGE_IO_HPP
#define SCAMP_IMAGE_IO_HPP
#include "image.hpp"
#include <iostream>
#include <iomanip>
#include <sstream>
#include <stdexcept>
inline uint64_t hex64(const std::string& s){return std::stoull(s,nullptr,16);}
inline ip6_t read_ip(){std::string a,b;std::cin>>a>>b;return {hex64(a),hex64(b)};}
inline void image_write_json(const ImageData& d){
    auto loc=[](ImageLoc x){std::cout<<'['<<x.stage<<','<<x.cell<<']';};
    auto fronts=[&](const std::vector<ImageFront>& v,int width){
        std::cout<<'[';bool first=true;
        for(auto e:v){if(!first)std::cout<<',';first=false;std::ostringstream key;key<<std::hex<<std::setfill('0')<<std::setw(width)<<e.key;
            std::cout<<"[\""<<key.str()<<"\","<<e.loc.stage<<','<<e.loc.cell<<']';}
        std::cout<<']';};
    std::cout<<"{\"root\":";if(d.root.stage<0)std::cout<<"null";else loc(d.root);
    std::cout<<",\"front16\":";fronts(d.front16,4);std::cout<<",\"front64\":";fronts(d.front64,16);
    std::cout<<",\"cells\":[";for(int s=0;s<RAM_NUM;++s){if(s)std::cout<<',';std::cout<<d.cells[s];}
    std::cout<<"],\"banks\":[";for(int s=0;s<RAM_NUM;++s){if(s)std::cout<<',';std::cout<<'[';bool first=true;
        for(const auto& word:d.banks[s]){if(!first)std::cout<<',';first=false;std::cout<<'"'<<image_word_hex(word)<<'"';}std::cout<<']';}
    std::cout<<"],\"bitmaps\":[";for(size_t i=0;i<d.bitmaps.size();++i){if(i)std::cout<<',';std::ostringstream mask;mask<<std::hex<<std::setfill('0')<<std::setw(16)<<d.bitmaps[i];std::cout<<'"'<<mask.str()<<'"';}
    std::cout<<"],\"nexthops\":[";for(size_t i=0;i<d.nexthops.size();++i){if(i)std::cout<<',';std::cout<<d.nexthops[i];}std::cout<<"]}";
}
inline ImageData image_read_wire(){
    ImageData d;std::cin>>d.root.stage>>d.root.cell;
    for(auto* v:{&d.front16,&d.front64}){size_t n;std::cin>>n;v->resize(n);for(auto& e:*v){std::string key;std::cin>>key>>e.loc.stage>>e.loc.cell;e.key=hex64(key);}}
    for(auto& n:d.cells)std::cin>>n;
    for(auto& bank:d.banks){size_t n;std::cin>>n;bank.resize(n);for(auto& word:bank){std::string text;std::cin>>text;word=image_word_from_hex(text);}}
    size_t n;std::cin>>n;d.bitmaps.resize(n);for(auto& mask:d.bitmaps){std::string text;std::cin>>text;mask=hex64(text);}
    std::cin>>n;d.nexthops.resize(n);for(auto& hop:d.nexthops)std::cin>>hop;
    if(!std::cin)throw std::runtime_error("wire input");return d;
}
#endif
